def migrate_course_videos_and_seed_pricing(apps, schema_editor):
    Course = apps.get_model('courses', 'Course')
    Lesson = apps.get_model('courses', 'Lesson')
    PricingRule = apps.get_model('courses', 'PricingRule')

    # Seed default pricing rules (Open Decision 7)
    PricingRule.objects.get_or_create(
        category='academic',
        defaults={'min_per_hour': Decimal('50.00'), 'max_per_hour': Decimal('150.00')},
    )
    PricingRule.objects.get_or_create(
        category='non_academic',
        defaults={'min_per_hour': Decimal('200.00'), 'max_per_hour': Decimal('600.00')},
    )

    # For each existing Course.video_file, create one Lesson and transfer status
    for course in Course.objects.all():
        if getattr(course, 'is_published', False):
            course.status = 'published'
        else:
            course.status = 'draft'

        video = getattr(course, 'video_file', None)
        if video:
            Lesson.objects.create(
                course=course,
                title=f"{course.title} - Video",
                order=1,
                video_file=video,
                duration_seconds=10,
                is_free_preview=False,
            )
            course.total_duration_seconds = 10
        course.save()


